// Ultra-fast Local Offline SDK for Racing Limits 1:1 HD Clone
// Features: All 35 Cars Unlocked, 999,999,999 Cash, 999,999 Gold, All 80 Levels, Zero Ads, Direct Garage Boot
(function() {
  console.log('[CrazyGames Local SDK] Initializing unlocked offline SDK (All Cars Free & Ad-Free)...');

  const storagePrefix = 'RacingLimits_Save_';

  // Pre-baked unlocked save data template
  const DEFAULT_UNLOCKED_SAVE = "";

  // Dynamic transformer: guarantees 999M Cash, 999K Gold, and all 35 cars + 80 levels unlocked + direct garage boot
  function makeEverythingFree(b64) {
    if (!b64 || typeof b64 !== 'string') return DEFAULT_UNLOCKED_SAVE;
    try {
      const binStr = atob(b64);
      const bytes = new Uint8Array(binStr.length);
      for (let i = 0; i < binStr.length; i++) bytes[i] = binStr.charCodeAt(i);
      let decoded = new TextDecoder('utf-16le').decode(bytes);

      // 0. Ensure direct garage boot (bypass tutorial highway)
      decoded = decoded.replace('TutorialShown@False%b', 'TutorialShown@True%b');

      // 1. Unlock all 35 cars
      decoded = decoded.replace(/asd312\d+@False%b/g, function(m) { return m.replace('False', 'True'); });

      // 2. Set 999,999,999 Cash
      decoded = decoded.replace(/48s77qdop@\d+%l/g, '48s77qdop@999999999%l');

      // 3. Set 999,999 Gold
      decoded = decoded.replace(/8hv2xbc@\d+%l/g, '8hv2xbc@999999%l');

      // 4. Unlock all 80 career levels
      decoded = decoded.replace(/48usdhxj\d+@False%b/g, function(m) { return m.replace('False', 'True'); });
      decoded = decoded.replace(/3a123kxj\d+@False%b/g, function(m) { return m.replace('False', 'True'); });
      decoded = decoded.replace(/57dsdkxp\d+@False%b/g, function(m) { return m.replace('False', 'True'); });

      // Encode back to UTF-16LE base64
      const outBytes = new Uint8Array(decoded.length * 2);
      for (let i = 0; i < decoded.length; i++) {
        const code = decoded.charCodeAt(i);
        outBytes[i * 2] = code & 0xff;
        outBytes[i * 2 + 1] = (code >> 8) & 0xff;
      }
      let binary = '';
      for (let i = 0; i < outBytes.length; i++) binary += String.fromCharCode(outBytes[i]);
      return btoa(binary);
    } catch(e) {
      console.error('[CrazyGames SDK] makeEverythingFree error:', e);
      return b64;
    }
  }

  const SDK = {
    environment: 'local',

    init: function(options) {
      console.log('[CrazyGames Local SDK] init() called with options:', options);
      return Promise.resolve({
        userInfo: null,
        gameInfo: { id: "22275", name: "Racing Limits" }
      });
    },

    data: {
      getItem: function(key) {
        try {
          let val = localStorage.getItem(storagePrefix + key);
          if (!val && (key === 'cgSave03_a' || key === 'cgSave03_b' || key === 'cgSave03_local')) {
            val = DEFAULT_UNLOCKED_SAVE;
            localStorage.setItem(storagePrefix + key, val);
          }
          if (val && (key === 'cgSave03_a' || key === 'cgSave03_b' || key === 'cgSave03_local')) {
            val = makeEverythingFree(val);
          }
          return val !== null ? val : '';
        } catch (e) {
          console.error('[CrazyGames Local SDK] getItem error:', e);
          return (key.startsWith('cgSave03')) ? DEFAULT_UNLOCKED_SAVE : '';
        }
      },
      setItem: function(key, value) {
        try {
          if (key === 'cgSave03_a' || key === 'cgSave03_b' || key === 'cgSave03_local') {
            value = makeEverythingFree(value);
          }
          localStorage.setItem(storagePrefix + key, value);
        } catch (e) {
          console.error('[CrazyGames Local SDK] setItem error:', e);
        }
      },
      removeItem: function(key) {
        try {
          localStorage.removeItem(storagePrefix + key);
        } catch (e) {}
      },
      clear: function() {
        try {
          Object.keys(localStorage).forEach(function(k) {
            if (k.startsWith(storagePrefix)) localStorage.removeItem(k);
          });
        } catch (e) {}
      },
      syncUnityGameData: function() {
        return Promise.resolve();
      }
    },

    ad: {
      hasAdblock: function() {
        // Report adblock present so ad scripts are never fetched
        return Promise.resolve(true);
      },
      prefetchAd: function() {
        return Promise.resolve();
      },
      addAdblockPopupListener: function() {},
      requestAd: function(adType, callbacks) {
        console.log('[CrazyGames Local SDK] requestAd intercepted:', adType);
        
        // Midroll (Interstitial / Pause ads / Level transitions):
        // SKIPPED COMPLETELY without pausing gameplay or muting audio!
        if (adType === 'midroll') {
          console.log('[CrazyGames Local SDK] Midroll ad completely blocked and skipped (NO GAME PAUSE).');
          try { window.dispatchEvent(new CustomEvent('unityGameplayCrash')); } catch(e) {}
          if (callbacks && typeof callbacks.adFinished === 'function') {
            try { callbacks.adFinished(); } catch (e) {}
          }
          return Promise.resolve();
        }

        // Rewarded ads (e.g. Free NOS, Free Cash):
        // Instantly grant reward without pausing or showing any ad video!
        if (callbacks) {
          if (typeof callbacks.adStarted === 'function') {
            try { callbacks.adStarted(); } catch (e) {}
          }
          if (typeof callbacks.adFinished === 'function') {
            try { callbacks.adFinished(); } catch (e) {}
          }
        }
        return Promise.resolve();
      }
    },

    game: {
      // Disallow pausing game during ads
      settings: { sound: true, music: true, pauseGameDuringAd: false },
      inviteParams: {},
      gameplayStart: function() {
        console.log('[CrazyGames Local SDK] gameplayStart()');
        try {
          window.dispatchEvent(new CustomEvent('unityGameplayStart'));
        } catch(e) {}
      },
      gameplayStop: function() {
        console.log('[CrazyGames Local SDK] gameplayStop()');
        try {
          window.dispatchEvent(new CustomEvent('unityGameplayStop'));
        } catch(e) {}
      },
      happytime: function() {
        console.log('[CrazyGames Local SDK] happytime()');
      },
      addSettingsChangeListener: function() {},
      showInviteButton: function() {},
      hideInviteButton: function() {},
      inviteLink: function(params) {
        const url = new URL(window.location.href);
        if (params) {
          Object.keys(params).forEach(function(k) { url.searchParams.set(k, params[k]); });
        }
        return url.toString();
      },
      addJoinRoomListener: function(cb) {
        window.__joinRoomListener = cb;
      },
      removeJoinRoomListener: function() {
        window.__joinRoomListener = null;
      },
      updateRoom: function() {},
      leftRoom: function() {}
    },

    user: {
      isUserAccountAvailable: false,
      getUser: function() {
        return Promise.resolve(null);
      },
      getUserToken: function() {
        return Promise.resolve("");
      },
      getXsollaUserToken: function() {
        return Promise.resolve("");
      },
      systemInfo: {
        countryCode: "BD",
        browser: { name: "Chrome", version: "120" },
        os: { name: "Windows", version: "10" },
        device: { type: "desktop" }
      },
      addAuthListener: function() {},
      showAuthPrompt: function() {},
      showAccountLinkPrompt: function() {},
      addScore: function(score) {
        console.log('[CrazyGames Local SDK] Score added:', score);
      },
      submitScore: function(score) {
        console.log('[CrazyGames Local SDK] Score submitted:', score);
      },
      listFriends: function() {
        return Promise.resolve([]);
      }
    },

    analytics: {
      trackOrder: function(order) {
        console.log('[CrazyGames Local SDK] Track order:', order);
      }
    },

    banner: {
      requestOverlayBanners: function(banners, cb) {
        console.log('[CrazyGames Local SDK] Banner ads completely disabled.');
        if (typeof cb === 'function') cb('blocked', 'Banners disabled', null);
      }
    }
  };

  window.CrazyGames = {
    SDK: SDK
  };
  window.crazygames = window.CrazyGames;
  console.log('[CrazyGames Local SDK] Unlocked offline SDK ready. All 35 Cars Free & Zero Ads active!');
})();
